/// The 18 default-avatar gradients, in the order AvatarPalette declares them.
///
/// Pick with `crc32(seed) % 18`, seeded `user:{id}` (or `room:{id}`), so one
/// person keeps one colour everywhere. The ORDER is load-bearing: reordering
/// this list repaints every member in the product.
///
/// Resolved from the compiled bundle, not typed by hand: Tailwind v4 stores
/// its palette in OKLCH, and the v3 hexes differ visibly on saturated hues.
abstract final class CnAvatarPalette {
  static const gradients = <List<Color>>[
    [Color(0xFFFF637E), Color(0xFFEC003F)], // rose-400 -> rose-600
    [Color(0xFFFB64B6), Color(0xFFE60076)], // pink-400 -> pink-600
    [Color(0xFFED6AFF), Color(0xFFC800DE)], // fuchsia-400 -> fuchsia-600
    [Color(0xFFC27AFF), Color(0xFF9810FA)], // purple-400 -> purple-600
    [Color(0xFFA684FF), Color(0xFF7F22FE)], // violet-400 -> violet-600
    [Color(0xFF7C86FF), Color(0xFF4F39F6)], // indigo-400 -> indigo-600
    [Color(0xFF51A2FF), Color(0xFF155DFC)], // blue-400 -> blue-600
    [Color(0xFF00BCFF), Color(0xFF0084D1)], // sky-400 -> sky-600
    [Color(0xFF00B8DB), Color(0xFF007595)], // cyan-500 -> cyan-700
    [Color(0xFF00D5BE), Color(0xFF009689)], // teal-400 -> teal-600
    [Color(0xFF00D492), Color(0xFF009966)], // emerald-400 -> emerald-600
    [Color(0xFF00C950), Color(0xFF008236)], // green-500 -> green-700
    [Color(0xFF7CCF00), Color(0xFF497D00)], // lime-500 -> lime-700
    [Color(0xFFFFB900), Color(0xFFE17100)], // amber-400 -> amber-600
    [Color(0xFFFF8904), Color(0xFFF54900)], // orange-400 -> orange-600
    [Color(0xFFFF6467), Color(0xFFE7000B)], // red-400 -> red-600
    [Color(0xFF64748B), Color(0xFF334155)], // slate-500 -> slate-700
    [Color(0xFF79716B), Color(0xFF44403B)], // stone-500 -> stone-700
  ];
}

